"""An approximate inverse is only a candidate; interval residuals certify it."""


def _finite(A):
    return all(A[i,j].is_finite() for i in range(A.nrows()) for j in range(A.ncols()))


def outward_round_matrix(original,bits):
    """Round every entry outward and check containment of the supplied balls."""
    from flint import arb_mat,ctx
    if not isinstance(bits,int) or bits<32:raise ValueError('Explicit precision of at least32 bits required')
    if not _finite(original):raise ValueError('Finite input balls required')
    previous=ctx.prec
    try:
        ctx.prec=bits
        rounded=arb_mat(original.nrows(),original.ncols(),
            [+original[i,j] for i in range(original.nrows()) for j in range(original.ncols())])
        contained=sum(rounded[i,j].contains(original[i,j])
            for i in range(original.nrows()) for j in range(original.ncols()))
        count=original.nrows()*original.ncols()
        if contained!=count:raise ArithmeticError('Outward input containment failed')
        return rounded,dict(rounding_bits=bits,input_entries=count,containment_checks=contained,
            all_rounded_entries_contain_originals=True)
    finally:ctx.prec=previous


def approximate_inverse_candidate(A,bits):
    """One approximate solve, without an error-bound or rank claim."""
    from flint import arb_mat,ctx
    if A.nrows()!=A.ncols() or not _finite(A):raise ValueError('Finite square input required')
    if not isinstance(bits,int) or bits<32:raise ValueError('Explicit candidate precision required')
    previous=ctx.prec
    try:
        ctx.prec=bits;n=A.nrows()
        approximate_input=arb_mat(n,n,[+A[i,j] for i in range(n) for j in range(n)])
        identity=arb_mat(n,n,[int(i==j) for i in range(n) for j in range(n)])
        candidate=approximate_input.solve(identity,algorithm='approx').mid()
        if not _finite(candidate) or not all(candidate[i,j].is_exact() for i in range(n) for j in range(n)):
            raise ArithmeticError('A finite exact dyadic candidate was not returned')
        return candidate
    finally:ctx.prec=previous


def inverse_residual_certificate(A,R0,bits):
    """Enclose I-R0*A; only a strict infinity-norm bound below one passes."""
    from flint import arb,arb_mat,ctx
    n=A.nrows()
    if A.ncols()!=n or R0.nrows()!=n or R0.ncols()!=n or not _finite(A) or not _finite(R0):
        raise ValueError('Finite matching square matrices required')
    if not all(R0[i,j].is_exact() for i in range(n) for j in range(n)):
        raise ValueError('The preconditioner must be frozen as exact dyadic entries')
    if not isinstance(bits,int) or bits<32:raise ValueError('Explicit verification precision required')
    previous=ctx.prec
    try:
        ctx.prec=bits
        identity=arb_mat(n,n,[int(i==j) for i in range(n) for j in range(n)])
        error=identity-R0*A
        if not _finite(error):raise ArithmeticError('Nonfinite inverse-residual enclosure')
        row_upper=[sum((abs(error[i,j]) for j in range(n)),arb(0)).upper() for i in range(n)]
        delta=max(row_upper);passed=bool(delta<1)
        norm_R0=max(sum((abs(R0[i,j]) for j in range(n)),arb(0)).upper() for i in range(n))
        inverse_bound=(norm_R0/(1-delta)).upper() if passed else None
        return dict(passed=passed,error=error,row_sum_upper=row_upper,delta_upper=delta,
            candidate_norm_upper=norm_R0,inverse_norm_upper=inverse_bound,verification_bits=bits,
            candidate_alone_is_certificate=False)
    finally:ctx.prec=previous
